insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5476,73,1,'يَـٰٓأَيُّهَا ٱلْمُزَّمِّلُ','bef974c820d833963288d5ecc7f1c1ce9b6275aaf5aa1bde83e796f7b0a23f85',29,574,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5477,73,2,'قُمِ ٱلَّيْلَ إِلَّا قَلِيلًا','75304e9492e69819723c6c96c3dcf211ed390a91ee1aa8d9b6a9739f59ff32d0',29,574,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5478,73,3,'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا','eff79792a5e29bc28cde63e23cc426dc714647bae8c5f5bc344edaf25a0717aa',29,574,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5479,73,4,'أَوْ زِدْ عَلَيْهِ وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا','8e25bfd3049c478c7b5bbfb14f3ca6af6a49c611e8e37f9fe0354a968080ae8f',29,574,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5480,73,5,'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا','f95eab06acb8e1f1fc8dd088807bc0b47a654c3ee5b2db4366d7a26e4989cdb3',29,574,1);
