insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5483,73,8,'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا','b221d3662abaa50dc3f7f5618dff8d0ce2fbe64336ff598485d70cbd3f1b6307',29,574,1);
