insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5487,73,12,'إِنَّ لَدَيْنَآ أَنكَالًا وَجَحِيمًا','adfe2c621cfa529389240a74711ac3e27b55b3292e3897d00fb19e71fac531cf',29,574,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5488,73,13,'وَطَعَامًا ذَا غُصَّةٍ وَعَذَابًا أَلِيمًا','dc83bc97b400d9ad63fd248b097eecb25245e1c33b088c23b50a3b761723426d',29,574,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5489,73,14,'يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًا مَّهِيلًا','28829d6eb356f3aed50db32660f82d76733fe79467dcb998a94b8a53781f40b1',29,574,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (5490,73,15,'إِنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولًا شَـٰهِدًا عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولًا','5940ad9018557c03dc6444fa2c5d98e61fda6be8b09aebb2ff56a2e930c22202',29,574,1);
